Generated Query:
PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?premiumAmount
       (COUNT(DISTINCT ?claim) AS ?numberOfClaims)
       (SUM(?claimTotalLoss) AS ?totalLoss)
       ((SUM(?claimTotalLoss) / ?premiumAmount) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .

    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumAmount .

    ?claim a in:Claim ;
           in:against ?pcd .

    OPTIONAL {
      SELECT ?claim (SUM(?lpAmt) AS ?sumLP)
      WHERE {
        ?claim in:hasLossPayment ?lp .
        ?lp in:lossPaymentAmount ?lpAmt .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?lrAmt) AS ?sumLR)
      WHERE {
        ?claim in:hasLossReserve ?lr .
        ?lr in:lossReserveAmount ?lrAmt .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?epAmt) AS ?sumEP)
      WHERE {
        ?claim in:hasExpensePayment ?ep .
        ?ep in:expensePaymentAmount ?epAmt .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?erAmt) AS ?sumER)
      WHERE {
        ?claim in:hasExpenseReserve ?er .
        ?er in:expenseReserveAmount ?erAmt .
      }
      GROUP BY ?claim
    }

    BIND(
      COALESCE(?sumLP, 0) +
      COALESCE(?sumLR, 0) +
      COALESCE(?sumEP, 0) +
      COALESCE(?sumER, 0)
      AS ?claimTotalLoss
    )
  }
}
GROUP BY ?policyNumber ?premiumAmount
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolder ?policyHolderId (SUM(?amount) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?policy in:hasPolicyHolder ?policyHolder .
    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }

    ?coverageDetail in:hasPolicy ?policy ;
                    in:hasPremiumAmount ?premium .

    ?premium in:premiumAmount ?amount .
  }
}
GROUP BY ?policyHolder ?policyHolderId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent .
    ?agent in:agentId ?agentId .
  }
}
GROUP BY ?agentId
ORDER BY ?agentId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?openDate ?closeDate
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .
    OPTIONAL { ?claim in:claimOpenDate ?openDate . }
    OPTIONAL { ?claim in:claimCloseDate ?closeDate . }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber
       (COALESCE(SUM(?lossPaymentAmt), 0) +
        COALESCE(SUM(?lossReserveAmt), 0) +
        COALESCE(SUM(?expensePaymentAmt), 0) +
        COALESCE(SUM(?expenseReserveAmt), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?claimNumber
ORDER BY ?claimNumber
